with parsed as (select id, host, payload_json, shiftright(status_code, 2) as status_code_high, array_contains(map_keys(context), 'trace') as has_trace from app_logs) select host, percentile_approx(status_code_high, array(0.25, 0.5, 0.75)) as status_code_high_quartiles, sort_array(collect_set(host)) as host_list, avg(status_code_high) as avg_status_code_high, sum(case when host = 'h1' then status_code_high else 0 end) as h1_status_code_high from parsed group by 1;
